// 定义电机的各种状态
typedef enum {
    MOTOR_IDLE,
    MOTOR_START,
    MOTOR_WAITING,
    MOTOR_STOP
} MotorState_t;

void motor_task_process(void) {
    static MotorState_t state = MOTOR_IDLE; // 静态变量，保存当前状态
    static uint32_t start_time = 0;         // 记录起始时间

    switch (state) {
        case MOTOR_IDLE:
            if (get_button_pressed()) {
                state = MOTOR_START;
            }
            break;

        case MOTOR_START:
            turn_on_motor();
            start_time = get_system_tick(); // 获取当前系统毫秒数
            state = MOTOR_WAITING;
            break;

        case MOTOR_WAITING:
            // 非阻塞检查：当前时间 - 起始时间 >= 2000ms
            if (get_system_tick() - start_time >= 2000) {
                state = MOTOR_STOP;
            }
            // 如果没到 2 秒，立刻退出 switch，不阻塞 CPU！
            break;

        case MOTOR_STOP:
            turn_off_motor();
            state = MOTOR_IDLE;
            break;
    }
}
